<script setup lang="ts">
import { computed, ref, watch } from 'vue';import ActionIcon from './ActionIcon.vue';import PageActions from './PageActions.vue';import SnapshotGate from './SnapshotGate.vue';import DataGrid from './DataGrid.vue';import { captureScheduleSource } from '../data/snapshot-schedule';
const props=defineProps<{items:{id:string;name:string;namespace?:string}[];selected:string[];execute:(ids:string[],backupId:string)=>Promise<void>|void;verb?:string}>();const emit=defineEmits<{ 'update:selected':[ids:string[]] }>();const reviewing=ref(false),ready=ref(false),confirmed=ref(false),busy=ref(false),error=ref('');const gate=ref<any>(null);const affected=computed(()=>props.items.filter(i=>props.selected.includes(i.id)));const captured=ref<any>(null);watch(affected,()=>{confirmed.value=false;},{deep:true});const scope=computed(()=>JSON.stringify(captured.value));function review(){captured.value=captureScheduleSource();reviewing.value=true;ready.value=false;confirmed.value=false;error.value='';}
async function commit(){if(!confirmed.value||!gate.value?.checkNow())return;busy.value=true;try{if(JSON.stringify(captureScheduleSource())!==scope.value)throw new Error('Configuration changed during review. Reopen deletion and take a fresh snapshot.');await props.execute(affected.value.map(i=>i.id),gate.value.snapshotId());emit('update:selected',[]);reviewing.value=false;}catch(e){error.value=e instanceof Error?e.message:'Deletion failed.';}finally{busy.value=false;}}
</script>
<template><PageActions><button v-if="affected.length" type="button" class="bulk-delete" @click="review"><ActionIcon icon="delete"/>Delete {{ affected.length }} Items</button></PageActions><Teleport to="body"><div v-if="reviewing" class="bulk-overlay snm" role="dialog" aria-modal="true" aria-label="Delete Selected Items"><section class="bulk-review"><h2>Delete {{ affected.length }} Items</h2><p>{{ verb || 'Queue configuration deletions for application in Pending Rollouts.' }} Secrets are preserved.</p><DataGrid><thead><tr><th>Item</th><th>Namespace</th></tr></thead><tbody><tr v-for="item in affected" :key="item.id"><td>{{ item.name }}</td><td>{{ item.namespace || 'Global' }}</td></tr></tbody></DataGrid><SnapshotGate ref="gate" :scope-key="scope" :data="captured" @ready="ready=$event; confirmed=false" /><label class="bulk-confirm"><input v-model="confirmed" type="checkbox" :disabled="!ready">Yes, Delete {{ affected.length }} Selected Items</label><p v-if="error" role="alert">{{ error }}</p><div class="bulk-buttons"><button type="button" :disabled="!ready||!confirmed||busy" @click="commit">Confirm Delete</button><button type="button" :disabled="busy" @click="reviewing=false">Cancel</button></div></section></div></Teleport></template>
<style>.bulk-overlay{position:fixed!important;inset:0;z-index:100;background:#000a;display:grid!important;place-items:center!important;height:100dvh!important}.bulk-review{background:#242c38;border:1px solid #619bd9;border-radius:8px;padding:24px;width:min(900px,94vw);max-height:90dvh;overflow:auto;font-size:12px}.bulk-review table{width:100%;border-collapse:collapse}.bulk-review th,.bulk-review td{text-align:left;padding:10px;border-bottom:1px solid #384352}.bulk-review p{line-height:1.6}.bulk-buttons{display:flex;gap:12px;margin-top:20px}.bulk-review button{font:inherit;background:#326fb4;color:white;border:0;border-radius:5px;padding:10px 14px;cursor:pointer}.bulk-review button:disabled{opacity:.5;cursor:not-allowed}.bulk-confirm{display:flex;align-items:center;gap:10px;margin-top:18px}</style>
